INSERT INTO `activities` VALUES (1,1,'Pertanyaan Pemantik','Mengamati fenomena pengukuran tinggi pohon & gedung tanpa memanjat.',0),(2,2,'LKPD Simulasi Konsep','Eksplorasi segitiga siku-siku & penemuan rasio sin, cos, tan.',1),(3,3,'Materi Trigonometri','Definisi sisi depan, samping, miring & mnemonik Demi-Sami-Desa.',1),(4,4,'Sudut Istimewa','Pembuktian geometris & tabel nilai sudut istimewa 0°, 30°, 45°, 60°, 90°.',1),(5,5,'Latihan Soal','5 butir latihan uji pemahaman konsep dasar dengan umpan balik instan.',1),(6,6,'Simulasi Terapan','3 Simulasi interaktif: Tinggi Pohon, Pendaratan Pesawat, Layang-layang.',1),(7,7,'Contoh Literasi Numerasi','5 Contoh soal kontekstual AKM/literasi numerasi dan pembahasannya.',1),(8,8,'Sumatif Literasi Numerasi','Asesmen sumatif terstruktur berbasis stimulus narasi dan diagram.',1),(9,9,'Refleksi Belajar','Evaluasi proses belajar dan pemahaman materi secara mandiri.',1),(10,10,'Hasil Belajar','Laporan akhir pencapaian, sertifikat kompetensi & umpan balik guru.',1);
